self.addEventListener("push", (event) => {
  if (event.data) {
    const { title, body, url } = event.data.json()
    event.waitUntil(self.registration.showNotification(title, {
      body, icon: "/app-icon-192.png", data: { url }
    }))
  }
})

self.addEventListener("notificationclick", (event) => {
  event.notification.close()
  const url = new URL(event.notification.data.url, self.location.origin)
  if (url.origin === self.location.origin) {
    event.waitUntil(openNotification(url))
  }
})

async function openNotification(url) {
  const windows = await self.clients.matchAll({ type: "window" })
  const existing = windows.find(client => client.url === url.href)
  return existing ? existing.focus() : self.clients.openWindow(url.href)
}

TurboOffline.start()
